    notes: 'כלל ולידציה: ב-15 חייב להיות זוג. אם יצא אי-זוג — הרמל שגוי. קטרי: ב15 מ-2 אי-זוגות. דלעי: ב15 מ-2 זוגות. חלק 1=עבר (אמות+מאזניהן), חלק 2=הווה (בנות+מאזניהן), חלק 3=עתיד (ב13,14,15).',
