    arabicText: `[המשך בית 11 מעמוד 51]
ومودة ، والتهيجات ، والعطف ، والمواعيد ، والنصرة ، واللطف ، والصلح ، والسخاء ، والكرم ، وكل عز من الأمور ، وبأس ، وأسباب التجارة ، والصلاح ، والريح ، والصالحين ، والراحة ، وأمور النساء ، وحبهم ، وعشقهم ؛ وهذا البيت يرث الحكم من البيتين : الخامس والسادس ؛ وللبيت : الساقين .
وشقوة : البيت الثاني عشر : جنوبي ، وساقط ، وصاعد ، وترابي ، وإنفصال ، وأنثى ، وملآن ؛ والشكل الحال فيه يسمى : تراب التراب ؛ وهو بيت الأعداء ، والخيل ، وذوات الحوافر ، والشقاء ، والشماتة ، والهم ، والغم ، والحسد ، والنميمة ، والزوال ، والشدة ، والمكث ، والتعقيد ، وما لا يتم ، وما لا يكون ، والكيمياء ، والسجان ، والقيود ، والظلمة ، والرهبان ، والقسيسين ، والشيء الذاهب المولى ، والركون إلى الظن ، والوسواس ، والوحدة ، والفكر ، وإختلاط العقل ، والرأي ، وما أصاب الأم ، وذوا وجهين ، وذوا لسانين ، والحاكة ، والدباغين ، والنواويس ، والعبادة ، وقلة الضحك ، وطول السكوت ؛ وهذا البيت يرث الحكم من البيتين : السابع والثامن ؛ وللبيت : القدمين .
وكل ما ذكرناه في البيوت الإثنى عشر ، هو : أصل الرمل والفلك ، الذي عليه الأحكام والمعول ، ويختص الرمل بذكر ما في`,
