    arabicText: `[جدول تسكين السكنى — ١٦ شكلاً في مواضعهم ١–١٦]

ويسمى : تسكين السكنى ، لأن كل شيء حل في بيته ، مثل بيت السلطان ، والوزير ، وغير ذلك من الأعيان ، حتى لو سكن شكل في بيت غيره ، أنكر عليه ؛ فهذه ستة عشر شكلا ، كل شكل في بيته دل على الضمير ، وعلى قوة البيت الذي يدل عليه الشكل ، فاحفظ هذه النكتة ، فإنها سر الضمائر ، وتحتاج إلى الحفظ غيبا .

التسكين الثاني : تسكين العدد والمدد :

وفيه ثلاثة أوجه ؛ ومعرفة ترتيبه بهذه الأبيات :

لأن كوسج الأحيان أدخل عتبة          بياض نقي الخد نخرجها قسرا
وإن حمرة الأنكيس في قبض داخل          وأت عقلة الإجماع أدخلت النصرا
فسل بطريق النصر عند خروجه          جماعته هل نصرة خرجت جهرا

وهذه صورته ، وما لكل شكل من العدد مكتوب فوقه ، وهو هكذا :`,
