    arabicText: `[המשך מעמ' 119 — דוגמת שיטת-המדד, המשך הדוגמה]
ووجدنا الأحيان ، المدة : ساعة أو يوم ؛ ولو وجدنا الأحيان ، في البنات ، لقلنا : المدة يوماً أو أسبوعاً ؛ ولو وجدناه في المنشآت ، لقلنا : أسبوع أو شهر ؛ ولو وجدناه في الموازين ، لقلنا : المدة شهر أو سنة .

وعلى الوجه الآخر : إن وجدنا الأحيان ، في الأمهات ، كان العدد درهماً واحداً ؛ وإن كان في البنات ، قلنا : عشرة دراهم ؛ وإن كان في المنشآت ، قلنا : مائة درهم ؛ ولو وجدناه في الموازين ، لقلنا : ألف درهم ؛ فافهم ذلك .

وجه آخر : إن وقع الشكل النار في الأمهات ، وكان الشكل الحمرة ، فالحمرة ، فيها نقطة محصورة وعدد إثنان ، فنقول : المدة ساعتان أو يومان ؛ أو يكون في البنات : المدة يومان أو أسبوعان ؛ أو يكون في المنشآت : فالمدة شهران أو سنتان .

وأما حكمها في العدد ـ أيضاً ـ : في محل الأيام : درهمان ؛ وفي محل الأسابيع : عشرون ؛ وفي محل الشهور : مائتا درهم ؛ وفي محل السنين : ألف درهم ؛ وهذا في جميع الأشكال على طريق العنصر ، فهذا وجه العمل بهذا العلم ، وما أجمعوا عليه أهل هذا الفن ، والله أعلم .`,
