    notes: 'ארבע הצורות הבסיסיות: אחיאן=צפרא(חם-יבש), חמרה=דם(חם-לח), ביאד=בלגם(קר-לח), אנכיס=סוודא(קר-יבש). תועלת התסכין: הכרת טבע השואל. שתי שיטות: (א) לפי מניין גדול, (ב) לפי בית-הד׳מיר. הכרעה: רק 4 האמהות בעלות טבע ודאי.',
