    arabicText: `الوجه الرابع : تعد نقط الجوهرين ، أعني : الخفيف والثقيل ، من المساءلة المضروبة ، من الأول إلى الخامس عشر ، ولا تدخل السادس عشر ، وتجمع عدد ذلك وتسقطه (١٢ ، ١٢) ، فما ألقه من الأول إلى حيث يقف ، فإن كان في بيته ففيه الضمير ، أو بيت من بيوت خطوطه ، فله الشركة في الضمير ، وإلا فامض به إلى بيته ، وتكلم على ذلك البيت مع الذي دل عليه ، وهو الضمير بعينه ، فلا يفوتك بوجه من الوجوه .

النوع الثاني : تنظر إلى شكل الميزان ، وما قوي فيه من العناصر ، فسيره إلى حيث يقف ، فإن كان ذلك البيت الذي وقف فيه حظ فيه ، أو له حظ فيه ، فهو الضمير ، وإلا فارجع به إلى بيته من تسكين السكنى ، ففيه الضمير لا يخطئك ، وانظر أصل تلك النقطة ، من أين إرتفعت ، فشاركه في الضمير ، وإن إتفق التسيير والنقطة فشاهدين أقوى من شاهد ، ففيه`,
