    arabicText: `عظيم ، لكن يخلص سريعا ؛ وإن كان السابع خارجا ، والثامن داخلا ، فلا يحصل له الخلاص وعلى زيادة ؛ وإن كان الطريق بالثالث عشر ، له سفر في شغل ؛ وإن كان التاسع خارجا ، والعاشر داخلا ، يأتي سريعا من سفره ؛ وإن كان التاسع داخلا ، والعاشر خارجا ، يطيع في سفره ، ويبقى زمانا طويلا ؛ وإن حل الطريق في الحادي عشر ، وكان الخامس داخلا ، والسادس خارجا ، يكون خوفا على المريض ؛ وإن كان الخامس خارجا ، والسادس داخلا ، يطيب المريض سريعا ويحصل المطلوب أيضا ؛ وإن حل الطريق في الرابع عشر ، وكان الحادي عشر داخلا ، والثاني عشر خارجا ، تبدل المشقة إلى الراحة ؛ وإن كان الطريق في الخامس عشر ، وكان الثالث عشر داخلا ، والرابع عشر داخلا ، وكان له مطلوب ، فلا يحصل ، والمريض على خوف وتشويش ؛ وإن كان الثالث عشر خارجا ، والرابع عشر داخلا ، كان من خير أو سلامة ؛ وإن كان الطريق في البيت السادس عشر ، وكان الخامس عشر داخلا ، والأول خارجا ، يكون في نعمة وسعادة وفرح وسرور ، والسفر مبارك .

فصل : يعتبر الطريق ، أسرع الأشكال في الحصول والدخول ، وبعده النصرة الداخلة ، لأنهما يدلان على`,
