    topics: ['אחים-גמר-בית5+13', 'מעבר-ממקום-למקום', 'בית4+15=סעיד-נחס-ממוזג', 'איזו-עיר-עדיפה', 'בית1+2-גובר=מקומו-עדיף', 'בית7+8-גובר=לעבור', 'המקום-טוב-לי', 'בית1+4-סעיד=להישאר', 'בית7+10-סעיד=לעבור', 'להישאר-או-לעבור', 'בית1-סעד+בית2-נחס=ישאר', 'בית1-נחס+בית2-סעד=יעבור'],
