    chapterHebrew: 'פרק רביעי: אבות נכסים וסודות — גוהר-הח׳בייה ומקומה, הוצאת-הח׳בייה בע-רבאע (16×4=94 בית)',
    arabicText: `عليه ، فحيث ما وجدت السعود فيه ، فاحكم له بالخير ، وحيث ما وجدت النحوس ، فاحكم بضده ، والإعتماد على الشواهد .

نكتة : في أحكام الخبايا : البيت الأول : هو جوهر الخبيئة ؛ والرابع : موضعها ؛ فإن كان الأول أرضيا ، فمن الأرض ؛ وإن يكون في ماني ، فمن البقول ؛ أو في بيت هواني ، فمن الحيوان .

نكتة : في إخراج الخبيئة : إذا أكملت المسللة ، خذ نقط النار من البيت ، مع عدد إسم صاحب الشكل ، وأسقط الجملة (4 ، 4 ، 4) ، فإن بقي واحد ، فهو في الركن الغربي ؛ وإن بقي إثنان ، فهو في الركن الشرقي ؛ وإن بقي ثلاثة ، فهو في الركن الجنوبي ؛ وإن بقي أربعة ، فهو في الركن الشمالي ؛ فإذا إنتهيت إلى ذلك الربع ، أخرج له أمهات ، أيضا ، وخذ نقط الهواء مع عدد إسم صاحب الطالع ، وأسقطه أيضا (4 ، 4 ، 4) ، ثم فعل بالباقي كما فعلت بالأول ، حتى تنتهي إلى الرابع المضروب ، فإنه لابد أن يطلع في ربع من الأرباع المضروبة في مثلها ، موضع الخبيئة ، وهي ستة عشر ، كل بيت مقسوم على أربعة أقسام ، فيكون مجموع ذلك أربعة وتسعين بيتا ، فاعلمه ، وهذا عمل طويل .`,
