    arabicText: `نكتة : في المريض : إن حل في السادس شكلا داخلا : كالقبض الداخل ، أو العتبة الداخلة ، أو النصرة الداخلة ، فاعلم أن المرض على زيادة ، والطريق ، في البيت الثالث والرابع ، دل على بياض الكفن ، وإن خرجت الطريق في بيت المسعود وشهد له السعد ، فهي طريق سلامته ؛ وإن خرجت في بيت نحس ، وشهد له النحوس ، فهي طريق الموت .

نكتة : للمريض : إن كان الأول ، والسادس ، والثامن ، والثاني عشر ، أشكال خفيفة تقضي الخروج ، دلت على العاقبة الحسنة ؛ وإن كانت أشكال ثقيلة دلت على الموت ، وإن نحست العاقبة ، دل على طول المرض .

وأما الدواب : فإن الحمرة ، في البيت السادس ، تدل على الكباش ؛ والتشمير ، يدل على الثيران ؛ والنصرة الخارجة ، والعتبة الخارجة ، تدل على الخيل ؛ والعقلة ، تدل على الجمال ؛ والأنكيس ، تدل على الحمير ؛ والأنكيس ، تدل على الجدية والتيوس ؛ والقبض الخارج ، يدل على البغال ؛ والحكم في جميع ذلك على قدر الشواهد .

نكتة : في الضال ورجوعها : أقصد البيتين الثامن والسادس ،`,
