    arabicText: `[تتمة الفصل السادس]: ... = القبر ؛ البيت الثاني في البيت التاسع = النقلة ؛ البيت الرابع في البيت الثاني عشر = النعش ؛ البيت الخامس في البيت السادس عشر = جموع المشيعين .

الفصل السابع : في التزويج والمقاصد والغالب والمغلوب والبيع والشراء

إن حلّت أشكال الزهرة في البيوت الأول والخامس والتاسع → التزويج يتمّ ؛ وكذلك المشتري .

البيت الأول في البيت السابع → حرة ؛ البيت السابع في البيت العاشر منقلبًا → مطلّقة ؛ ثابتًا → بكر .

السعد في البيت الثامن → المهر كبير ؛ السعد في البيت العاشر → أسرة كريمة ؛ النحس → وضيعة .

الشكل المولود من البيوت الأول والسابع والتاسع سعدًا → نفع منها ؛ نحسًا → ضده ؛ ممزوجًا أو مجسدًا → خير .

نكتة : هل ينظر إليك هذا الشخص أم إلى آخر ؟ نار البيت الأول تنحلّ + نار البيت السابع تنحلّ + نار البيت الثالث عشر تنضمّ [يتبع] ...`,
