    arabicText: `نكتة : للغلاء والرخص : خذ الثاني ، والخامس ، والعاشر ، والحادي عشر ، واجعلهم أمهات ، وكملهـ إلى السادس عشر ، واجمع عنصر النار والهواء وحده ، والماء والتراب وحده ، فإن زاد النار والهواء ولو بنقطة ، دل على الغلاء ؛ وإن زاد الماء والتراب ، دل على الرخص .

نكتة : للبيع والشراء : انظر إلى الأول ، والرابع ، والثاني ، والسابع ، والحادي عشر ، والخامس عشر ، والسادس عشر ، فإن كانت كلها أو أكثرها سعود داخلة ، تم الشراء على أيسر شيء ، وحسنت عاقبة المشتري ؛ ثم اجعل الأول والثاني للمبتاع ، والثامن والسابع للبائع ، والعاشر الدال ، والخامس عشر عاقبة ذلك ، فإن جاء الأول في الثامن ، كان المشتري أصلح من البائع ؛ وإن يكون الأول في العاشر ، كان المشتري أسمح من البائع ؛ ومتى سعدت الأوتاد والعاقبة ، دلت على الخروج ، وتصورت في البيوت القوية ، تم المبيع على المراد .

نكتة : في الطالب والمطلوب بالدائرة : اعلم أن كل شكل يظهر في الأول من التخت ، فعد من بيت شرفه إلى الأول ، واعرف مبلغ العدد ، ثم أسقطه من الأول على تسكين السكنى إلى حيث ينفذ ، فإن وقف العدد في بيوت سعيدة ، مثل : الأوتاد ، والخامس [يتبع] ...`,
