    arabicText: `الفصل الثامن : في السرقة والقرض :

أحكام السرقة : فالأول صاحب السرقة ، والسابع قد تكرر في بيت من البيوت ، فهو من سببه ، فإن كان تكرر في الأول ، فهو شخص يقيمه مقام نفسه ؛ وإن كان في الثاني ، فهو من أعوانه ؛ وإن كان في الثالث ، فهو السارق ؛ فإن كان في السابع ، صح إظهاره ؛ وإن كان في الرابع ، فممن يدخل داره ؛ وإن تكرر في الخامس ، فممن يعاشر ولده ؛ وإن تكرر في السادس ، فإنه يمرض بسبب السرقة ؛ وإن كان في الثامن سعد ، فإنه يظفر بالسرقة ؛ وإن كان فيه نحس ، فلا يظفر بها ؛ وإن يكون السابع في التاسع ، فمن سبب السفر ؛ وإن يكون في العاشر ، فإنه ممن يتصل بأرباب الحاكم ؛ وإن كان في الحادي عشر ، فإنه يتصل بأقوام يعاشرهم ؛ فبالذي يعاديهم ؛ والبيت الثاني هو صفة السارق فتعرف منه ؛ والبيت الثامن هو موضعه ما حصل بيده ؛ والرابع هو موضع السرقة ؛ فإن كان في العاشر سعيد داخل ، فإن السرقة في المدينة ؛ وإن كان نحس خارج ، فقد خرجت من المدينة .

نكتة : في جهات السرقة : إن كان في الرابع شكل شرقي ، فالسرقة ناحية المشرق ؛ وإن كان فيه شكل غربي ، فهي في [يتبع] ...`,
